// mt/sim/index.js — the Monster-Trainer sim hub. Installed on every legacy World as `world.mt`.
// Owner: architecture. Specialists do NOT edit this file to add behaviour: they register through
// `mt.on(hook, fn)` / `mt.impl.<name> = fn` from their own module's `install(mt)`.
//
// The legacy bundle (assets/index-DHK-Ptzs.js) calls the methods marked "LEGACY HOOK" below from code
// marked `// [MT-HOOK] <name>`. Each legacy call site is a one-liner guarded by `this.mt &&` / `e.mt &&`.
//
// `L` (the legacy API) is an object of internal bundle functions/tables handed over by the bundle at
// construction time; see the typedef below and README.md "Legacy API".

import '../net/importmath.js'; // FIRST: module-level Math (ai/geo.js lane lengths) gets the same bits on every engine (online lockstep)
import { MT_EVENT } from './events.js';
import * as rules from './rules.js';
import * as trainers from './trainers.js';
import * as monsters from './monsters.js';
import * as capture from './capture.js';
import * as progression from './progression.js';
import * as combat from './combat.js';
import * as minions from './minions.js';
import * as structures from './structures.js';
import * as jungle from './jungle.js';
import * as cards from './cards.js';
import * as debug from './debug.js';
import { defaultRoster } from './roster.js';
import * as trainerBot from '../ai/trainerBot.js';
import * as DATA_TYPES from '../data/types.js';
import * as DATA_SPECIES from '../data/species.js';
import * as DATA_ABILITIES from '../data/abilities.js';
import * as DATA_BALANCE from '../data/balance.js';
import * as DATA_OPTIONS from '../data/options.js';
import * as DATA_CARDS from '../data/cards.js';
import { guideFor } from './guide.js';
import '../net/importmath-end.js'; // LAST: native Math again (see ../net/importmath.js)

/**
 * @typedef {Object} LegacyAPI  internal functions of the legacy bundle (minified name in parentheses)
 * @property {Object} KIND (t)  @property {Object} TEAM (m)  @property {Object} EVENT (S)  @property {number} DT (n)
 * @property {Function} createBaseUnit (lS) (world, kind, team, x, y) -> unit
 * @property {Function} snapshotBaseStats (pS) (unit)
 * @property {Function} recomputeStats (fS) (unit)
 * @property {Function} dealDamage (_v) (world, src, target, amount, type, opts) -> dealt
 * @property {Function} heal (Sv) (world, unit, amount, silent, src)
 * @property {Function} addShield (Cv) (world, unit, amount, duration, type)
 * @property {Function} applyCC (Tv) (world, src, target, 'stun'|'root'|'silence'|'knockup'|'slow', dur, power)
 * @property {Function} addDot (Mv) (world, src, target, {id,total,duration,interval,type,fx})
 * @property {Function} addBuff (Fv) (world, unit, id, duration, stats, data, stacks)
 * @property {Function} getBuff (Iv) (unit, id)    @property {Function} removeBuff (Lv) (unit, id)
 * @property {Function} spawnProjectile (Rv) (world, opts)
 * @property {Function} startAttack (Xv) (world, unit, target) -> bool
 * @property {Function} cancelAttack (Qv) (world, unit, refund)
 * @property {Function} isTargetable (sv) (world, attacker, target)
 * @property {Function} edgeDist (cv)  @property {Function} edgeDistPrev (lv)
 * @property {Function} isStructure (rv)  @property {Function} isDisabled (Dv)  @property {Function} isImmobile (Ov)
 * @property {Object} CHAMPIONS (Kx)  @property {Object} MINION_CFG (R_)  @property {Object} JUNGLE_CFG (W)
 * @property {Object} TOWER_CFG (F_)  @property {Object} ECON_CFG (M_)  @property {Object} COMBAT_CFG (B_)  @property {Object} NAV_CFG (G)
 * @property {Function} spawnLegacyCampMonster (ES) (world, camp) -> unit
 */

const HOOK_NAMES = ['ready', 'preTick', 'postTick', 'playerUnit', 'damage', 'kill', 'command', 'cast'];

export class MTWorld {
  /** @param {object} world legacy World  @param {LegacyAPI} L */
  constructor(world, L) {
    this.world = world;
    this.L = L;
    this.KIND = L.KIND; this.TEAM = L.TEAM; this.EVENT = L.EVENT; this.DT = L.DT;
    this.E = MT_EVENT;
    /** @type {Record<string, Function[]>} multi-listener hooks */
    this.hooks = Object.fromEntries(HOOK_NAMES.map((k) => [k, []]));
    /** Single-owner decision points. Each module replaces the defaults it owns in its install(). */
    this.impl = {
      command: () => undefined,                // (mt, unit, cmd) -> true|false|undefined (undefined = let legacy handle)
      unitAI: () => {},                        // (mt, unit) for units with unit.mtCtl
      elementMult: () => 1,                    // (mt, src, tgt, dmgType, source, opts) -> number
      damageScale: (mt, ...a) => {             // (mt, src, tgt, dmgType, source, opts) -> number; default = product of mt.damageScalers
        let m = 1; for (const f of mt.damageScalers) m *= f(mt, ...a); return m;
      },
      creditOf: (mt, u) => u,                  // (mt, unit) -> unit credited for kills/assists (pet -> trainer)
      blockXp: () => false,                    // (mt, unit) -> true to block legacy champion XP
      towerTarget: () => undefined,            // (mt, tower) -> unit|null (undefined = legacy)
      campDefs: (mt, list) => list,            // (mt, legacyCampList) -> camp list
      spawnCamp: () => null,                   // (mt, camp, state) -> unit|null (null = legacy ES())
      waveComposition: () => undefined,        // (mt, team, lane, waveNo) -> string[]|undefined
      onMinion: () => {},                      // (mt, minion) after legacy factory
      minionAggro: () => undefined,            // (mt, minion, other) -> aggro class for trainers/mt monsters ([MT-HOOK] minionAggro; undefined = legacy)
      speedMult: () => 1,                      // unused by legacy directly; units carry unit.mtSpeedMul
    };
    this.stats = {
      captures: 0, captureAttempts: 0, captureFails: 0, evolutions: 0, levelUps: 0, faints: 0, swaps: 0,
      monsterCasts: 0, trainerSkills: 0, potions: 0, towerKills: [0, 0], trainerDeaths: 0, maxMonsterLevel: 0,
    };
    /** Shared damage scalar list: fn(mt, src, tgt, dmgType, source, opts) -> multiplier. Modules push() into it. */
    this.damageScalers = [];
    /** compact chronological log for the test harness: [{t, type, ...}] (bounded) */
    this.log = [];
    this.errors = {};
    this.legacyBotPhase = false;   // true while the legacy bot brain is issuing commands (see ai/trainerBot.js)
    this.nextRid = 1;
    this.net = null;               // online NetSession (mt/net/lockstep.js) while this world plays an online match
    // rules FIRST: match options (difficulty / mode / starters) are read by every other module (mt/sim/rules.js)
    this.modules = [rules, trainers, monsters, capture, progression, combat, minions, structures, jungle, cards, trainerBot, debug];
    for (const m of this.modules) if (m.install) m.install(this);
  }

  /** Register a listener: 'ready'|'preTick'|'postTick'|'playerUnit'|'damage'|'kill'|'command'|'cast'. */
  on(name, fn) { (this.hooks[name] || (this.hooks[name] = [])).push(fn); }

  /** Emit an mt event into the world event stream and the harness log. */
  emit(type, payload) {
    const ev = this.world.emit(type, payload);
    if (this.log.length > 4000) this.log.splice(0, 1000);
    this.log.push({ t: +this.world.time.toFixed(2), ...ev });
    return ev;
  }

  guard(key, fn) {
    try { return fn(); } catch (err) {
      const e = this.errors[key] || (this.errors[key] = { count: 0, last: '' });
      e.count++; e.last = String((err && err.stack) || err).slice(0, 600);
      if (e.count <= 3) console.error('[mt:' + key + ']', err);
      const app = typeof globalThis !== 'undefined' ? globalThis.__moba : null;
      if (app && app.errors) {
        const g = app.errors['mt:' + key] || (app.errors['mt:' + key] = { count: 0, last: '' });
        g.count++; g.last = e.last;
      }
      return undefined;
    }
  }

  _run(name, ...args) {
    const list = this.hooks[name];
    for (let i = 0; i < list.length; i++) this.guard(name, () => list[i](this, ...args));
  }

  // ------------------------------------------------------------------ LEGACY HOOKS (called from the bundle)
  /** [MT-HOOK] playerUnit — a champion unit was created for a roster entry (World constructor). */
  onPlayerUnit(unit, player) { this._run('playerUnit', unit, player); }
  /** [MT-HOOK] campDefs — filter/replace the jungle camp list before camps are seeded. */
  campDefs(list) { return this.guard('campDefs', () => this.impl.campDefs(this, list)) || list; }
  /** [MT-HOOK] ready — end of World constructor. */
  onWorldReady() { this._run('ready'); }
  /** [MT-HOOK] preTick — after time advanced and prev positions stored, before waves/camps/AI. */
  preTick() { this._run('preTick'); }
  /** [MT-HOOK] postTick — after movement/separation/vision, before dead-unit removal. */
  postTick() { this._run('postTick'); }
  /** [MT-HOOK] command — returns true/false to handle, undefined to let legacy process the command. */
  command(unit, cmd) {
    if (!unit || !cmd || typeof cmd !== 'object') return undefined;
    // online lockstep (mt/net/lockstep.js, set by mt/net/online.js): local human input is queued for tick + D and
    // applied on every peer in the same order; returns true/false then, undefined = handle now (bots, replay)
    if (this.net) { const q = this.net.intercept(unit, cmd); if (q !== undefined) return q; }
    return this.guard('command', () => this.impl.command(this, unit, cmd));
  }
  /** [MT-HOOK] unitAI — per-unit behaviour for units flagged `mtCtl` (pets, capturing/evolving monsters). */
  unitAI(unit) { this.guard('unitAI', () => this.impl.unitAI(this, unit)); }
  /** [MT-HOOK] damage (pre) — elemental multiplier. */
  elementMult(src, tgt, type, source, opts) {
    const v = this.guard('elementMult', () => this.impl.elementMult(this, src, tgt, type, source, opts));
    return Number.isFinite(v) ? v : 1;
  }
  /** [MT-HOOK] damage (pre) — every other mt damage scalar (spec, siege, evolution channel, tower ramp...). */
  damageScale(src, tgt, type, source, opts) {
    const v = this.guard('damageScale', () => this.impl.damageScale(this, src, tgt, type, source, opts));
    return Number.isFinite(v) ? v : 1;
  }
  /** [MT-HOOK] damage (post) — damage landed (participation, combat timers). */
  onDamage(src, tgt, amount, type, source, mult) { this._run('damage', src, tgt, amount, type, source, mult); }
  /** [MT-HOOK] kill credit — pet -> owner trainer for legacy credit/gold/assists. */
  creditOf(unit) { if (!unit) return unit; const v = this.guard('creditOf', () => this.impl.creditOf(this, unit)); return v || unit; }
  /** [MT-HOOK] kill (post) — after legacy death processing. killer = original damage source (may be a pet). */
  onKill(victim, killer, credited) { this._run('kill', victim, killer, credited); }
  /** [MT-HOOK] grantXp — true blocks legacy champion XP (trainers do not level). */
  blockXp(unit) { return !!this.guard('blockXp', () => this.impl.blockXp(this, unit)); }
  /** [MT-HOOK] towerTarget — unit/null to override, undefined for legacy. */
  towerTarget(tower) { return this.guard('towerTarget', () => this.impl.towerTarget(this, tower)); }
  /** [MT-HOOK] campSpawn — return a unit to replace the legacy jungle monster, or null for legacy. */
  spawnCamp(camp, state) { return this.guard('spawnCamp', () => this.impl.spawnCamp(this, camp, state)) || null; }
  /** [MT-HOOK] waveComposition */
  waveComposition(team, lane, waveNo) { return this.guard('waveComposition', () => this.impl.waveComposition(this, team, lane, waveNo)); }
  /** [MT-HOOK] minionSpawn */
  onMinion(unit) { this.guard('onMinion', () => this.impl.onMinion(this, unit)); }
}

/** Called by the legacy World constructor. */
export function installMT(world, legacy) { return new MTWorld(world, legacy); }

/** App-level namespace exposed as `window.__moba.mt` (see [MT-HOOK] app). */
export const MT_NS = {
  version: 1,
  data: { types: DATA_TYPES, species: DATA_SPECIES, abilities: DATA_ABILITIES, balance: DATA_BALANCE, options: DATA_OPTIONS, cards: DATA_CARDS },
  /** match options contract (mt/data/options.js): DEFAULT_OPTIONS, normalizeOptions, STARTERS ... */
  options: DATA_OPTIONS,
  /** objective guide for a trainer (mt/sim/guide.js); the app publishes it as `app.mtGuide(unitId?)` */
  guide: (world, unitId) => guideFor(world, unitId),
  events: MT_EVENT,
  roster: defaultRoster,
  /** debug helpers bound to the CURRENT world (`__moba.world.mt.debug`); see mt/sim/debug.js */
  get debug() { const app = globalThis.__moba; return app && app.world && app.world.mt ? app.world.mt.debug : null; },
};
